        case id = "id"
        case jsonrpc = "jsonrpc"
        case method = "method"
    }
}

enum TPJSONRPCID: Codable, Equatable, Sendable {
    case integer(Int)
    case string(String)

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let x = try? container.decode(Int.self) {
            self = .integer(x)
            return
        }
        if let x = try? container.decode(String.self) {
            self = .string(x)
            return
        }
        throw DecodingError.typeMismatch(TPJSONRPCID.self, DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Wrong type for TPJSONRPCID"))
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .integer(let x):
            try container.encode(x)
        case .string(let x):
            try container.encode(x)
        }
    }
}

