struct TPDurableEvent: Codable, Equatable, Sendable {
    let item: TPItem?
    let thread: TPThread?
    let threadID: String
    let turn: TPTurn?
    let type: TPEventType

    enum CodingKeys: String, CodingKey {
        case item = "item"
        case thread = "thread"
        case threadID = "threadId"
        case turn = "turn"
        case type = "type"
