}

enum TPEventType: String, Codable, Equatable, Sendable {
    case itemCompleted = "item.completed"
    case itemStarted = "item.started"
    case itemUpdated = "item.updated"
    case threadUpdated = "thread.updated"
    case turnUpdated = "turn.updated"
}

